22|static void push(TlTokVec *v, TlTokKind k, const char *t, int line) {
23|    if (v->count + 1 >= v->cap) {
24|        int nc = v->cap ? v->cap * 2 : 64;
25|        TlToken *ni = (TlToken*)realloc(v->items, (size_t)nc * sizeof *ni);
26|        if (!ni) return;
27|        v->items = ni; v->cap = nc;
28|    }
29|    TlToken *t2 = &v->items[v->count++];
30|    t2->kind = k; t2->line = line;
31|    t2->text = t ? (char*)malloc(strlen(t)+1) : NULL;
32|    if (t2->text) strcpy(t2->text, t);
