102|static int kw_match_at(const char *p, const char *kw) {
103|    size_t n = strlen(kw);
104|    if (strncmp(p, kw, n) != 0) return 0;
105|    /* Naechstes Zeichen darf kein Ident-Zeichen sein (ausser temporaere Namen sind exakt). */
106|    char c = p[n];
107|    if (c == '\0' || c == '\n' || c == '"' || c == ' ' || c == '\t' || c == '\r') return 1;
108|    return 0;
109|}
