111|int tl_lex(const char *src, const char *filename, TlTokVec *out) {
112|    (void)filename;
113|    int line = 1;
114|    const char *p = src;
115|    while (*p) {
116|        if (*p == '\n') { push(out, T_NEWLINE, NULL, line); line++; p++; continue; }
117|        if (*p == ' ' || *p == '\t' || *p == '\r') { p++; continue; }
118|        if (*p == '#') { while (*p && *p != '\n') p++; continue; }
119|        if (*p == '/' && p[1] == '/') { while (*p && *p != '\n') p++; continue; }
120|        if (*p == '"') {
121|            p++;
122|            char buf[4096]; size_t bl = 0;
123|            while (*p && *p != '"' && *p != '\n' && bl + 1 < sizeof buf) {
124|                if (*p == '\\' && p[1]) { buf[bl++] = *p++; buf[bl++] = *p++; }
125|                else buf[bl++] = *p++;
126|            }
127|            buf[bl] = '\0';
128|            if (*p == '"') p++;
129|            push(out, T_STRING, buf, line);
130|            continue;
131|        }
132|        int matched = 0;
133|        for (size_t i = 0; i < sizeof KWS / sizeof KWS[0]; i++) {
134|            if (kw_match_at(p, KWS[i].kw)) { push(out, KWS[i].kind, KWS[i].kw, line); p += strlen(KWS[i].kw); matched = 1; break; }
135|        }
136|        if (matched) continue;
137|        if (isalpha((unsigned char)*p) || *p == '_') {
138|            char buf[256]; size_t bl = 0;
139|            while ((isalnum((unsigned char)*p) || *p == '_') && bl + 1 < sizeof buf) buf[bl++] = *p++;
140|            buf[bl] = '\0';
141|            push(out, T_IDENT, buf, line);
142|            continue;
143|        }
144|        if (isdigit((unsigned char)*p) || (*p == '-' && isdigit((unsigned char)p[1]))) {
145|            char buf[64]; size_t bl = 0;
146|            if (*p == '-') buf[bl++] = *p++;
147|            while (isdigit((unsigned char)*p) && bl + 1 < sizeof buf) buf[bl++] = *p++;
148|            buf[bl] = '\0';
149|            push(out, T_NUMBER, buf, line);
150|            continue;
151|        }
152|        if (strchr("+-*/%<>=!&|()", *p)) {
153|            char buf[4] = {0};
154|            buf[0] = *p++;
155|            if ((buf[0]=='='||buf[0]=='!'||buf[0]=='<'||buf[0]=='>') && *p == '=') buf[1] = *p++;
156|            push(out, T_IDENT, buf, line);
157|            continue;
158|        }
159|        {
160|            char msg[128];
161|            snprintf(msg, sizeof msg, "Unbekanntes Zeichen '%c'", *p);
162|            out->error = (char*)malloc(strlen(msg)+1); strcpy(out->error, msg);
163|            out->error_line = line;
164|            return -1;
165|        }
166|    }
167|    push(out, T_EOF, NULL, line);
168|    return 0;
