15|static void emit_ident(FILE *out, const char *s) {
16|    if (!s) { fputs("/*null*/", out); return; }
17|    for (const char *p = s; *p; p++) {
18|        if (isalnum((unsigned char)*p) || *p == '_') fputc(*p, out);
19|        else fputc('_', out);
