34|static int gen_expr(TlNode *e, FILE *out, char **err) {
35|    if (!e) { *err = "fehlender Ausdruck"; return -1; }
36|    switch (e->kind) {
37|    case N_EXPR_NUM: fprintf(out, "%ldL", e->ival); return 0;
38|    case N_EXPR_STR: emit_cstr(out, e->sval); return 0;
39|    case N_EXPR_VAR:
40|        if (!is_valid_c_ident(e->name) && strcmp(e->name, "TEMP_Access_Do_Not_Use") != 0) { *err = "ungueltiger Variablenname"; return -1; }
41|        fputc('(', out); emit_ident(out, e->name); fputs(").num", out); return 0;
42|    case N_EXPR_NULL: fputs("NULL", out); return 0;
43|    case N_EXPR_BINOP:
44|        fputc('(', out);
45|        if (gen_expr(e->left, out, err)) return -1;
46|        fprintf(out, " %s ", e->sval);
