78|static void collect_uses_node(TlNode *s, NameSet *decl, NameSet *imp, int toplevel) {
79|    if (!s) return;
80|    switch (s->kind) {
81|    /* Nur Deklarationen der obersten Scope-Ebene zaehlen; Block-Deklarationen
82|       bleiben lokal (ggf. als legale Abschattung einer impliziten Anlage). */
83|    case N_VARDECL: if (toplevel) set_add(decl, s->name); break;
84|    case N_ASSIGN: collect_use_name(s->name, decl, imp); collect_uses_expr(s->left, decl, imp); break;
85|    case N_COPY: collect_use_name(s->name, decl, imp); collect_use_name(s->name2, decl, imp); break;
86|    case N_INC: case N_DEC: collect_use_name(s->name, decl, imp); break;
87|    case N_PRINT: collect_uses_expr(s->left, decl, imp); break;
88|    case N_NULL_SINK: collect_uses_expr(s->left, decl, imp); break;
89|    case N_IF: collect_uses_expr(s->cond, decl, imp); collect_uses_list(s->body, decl, imp, 0); collect_uses_list(s->else_body, decl, imp, 0); break;
90|    case N_WHILE: collect_uses_expr(s->cond, decl, imp); collect_uses_list(s->body, decl, imp, 0); break;
91|    case N_DIRECTIVE: collect_use_name(s->name, decl, imp); break;
92|    default: break;
93|    }
