98|    TlNodeList *l = body;
99|    /* Erster Durchlauf: alle VARDECL der obersten Ebene einsammeln. */
100|    for (; l; l = l->next)
101|        if (l->node->kind == N_VARDECL) set_add(&decl, l->node->name);
102|    NameSet imp; imp.n = 0;
103|    collect_uses_list(body, &decl, &imp, 1);
104|    for (int i = 0; i < imp.n; i++) {
105|        for (int k = 0; k < ind; k++) fputs("    ", out);
106|        fputs("TlVal ", out); emit_ident(out, imp.names[i]);
107|        fputs("; tl_val_init(&", out); emit_ident(out, imp.names[i]);
108|        fputs("); /* implizit: Verwendung ohne Deklaration */\n", out);
