133|        else if (e && e->kind == N_EXPR_NUM) { fputs("tl_val_set_num(&", out); emit_ident(out, s->name); fprintf(out, ", %ldL);\n", e->ival); }
134|        else if (e && e->kind == N_EXPR_NULL) { fputs("tl_val_set_null(&", out); emit_ident(out, s->name); fputs(");\n", out); }
135|        else if (e && e->kind == N_EXPR_VAR) { fputs("tl_val_copy(&", out); emit_ident(out, s->name); fputs(", &", out); emit_ident(out, e->name); fputs(");\n", out); }
136|        else { fputs("tl_val_set_num(&", out); emit_ident(out, s->name); fputs(", ", out); if (gen_expr(e, out, err)) return -1; fputs(");\n", out); }
137|        return 0;
138|    }
139|    case N_COPY:
140|        indent(out, ind); fputs("tl_val_copy(&", out);
