37|static int translate(const char *in_path, const char *c_path) {
38|    long n = 0; char *src = read_file(in_path, &n);
39|    if (!src) { fprintf(stderr, "Fehler: Datei nicht gefunden: %s\n", in_path); return 1; }
40|    TlTokVec vec; tl_tokens_init(&vec);
41|    if (tl_lex(src, in_path, &vec)) {
42|        fprintf(stderr, "Lexerfehler in %s, Zeile %d: %s\n", in_path, vec.error_line, vec.error);
43|        tl_tokens_free(&vec); free(src); return 2;
44|    }
45|    char *err = NULL; int el = 0;
46|    TlNode *prog = tl_parse(&vec, &err, &el);
47|    if (!prog) { fprintf(stderr, "Syntaxfehler in %s: %s\n", in_path, err ? err : "?"); free(err); tl_tokens_free(&vec); free(src); return 2; }
48|    FILE *o = fopen(c_path, "w");
49|    if (!o) { fprintf(stderr, "Fehler: kann %s nicht schreiben\n", c_path); tl_node_free(prog); tl_tokens_free(&vec); free(src); return 1; }
50|    char *cerr = NULL;
51|    int rc = tl_codegen(prog, o, &cerr);
52|    fclose(o);
53|    if (rc) fprintf(stderr, "Codegenfehler: %s\n", cerr ? cerr : "?");
54|    tl_node_free(prog); tl_tokens_free(&vec); free(src);
55|    return rc ? 3 : 0;
