73|        char *err = NULL; int el = 0;
74|        TlNode *prog = tl_parse(&vec, &err, &el);
75|        if (!prog) { fprintf(stderr, "Syntaxfehler: %s\n", err); free(err); tl_tokens_free(&vec); free(src); return 2; }
76|        tl_explain(prog, stdout);
77|        tl_node_free(prog); tl_tokens_free(&vec); free(src);
